 function enter(s,id){const n=scene(id);if(s.current_scene&&s.current_scene!==id&&!s.commits[s.current_scene])throw Error('Current scene is not completed');if(!s.entered[id]&&id!==nodes[0].node_id){const previous=nodes.find(x=>x.next_node===id);if(previous&&!s.commits[previous.node_id])throw Error('Scene is not unlocked');}s.current_scene=id;s.entered[id]=true;s.time.story_day=Math.max(s.time.story_day,Math.min(7,Math.ceil(Number(n.chapter_id.slice(2))*7/16)));return n;}
 function remember(s,n,event){const record={event_id:event.event_id,source:'player_statement',timestamp_story:s.time.story_day,observers:[...presentation(s,n.node_id).characters,...presentation(s,n.node_id).remote],privacy_classification:'case_private',consent_to_recall:false,confidence:1,...event};s.memory.push(record);return record;}
 function needsConfirmation(text){const t=String(text||'').trim();if(/(?:不要|不许|不想|拒绝|别|do not|don't|never|won't|not going to)/i.test(t))return false;return /公开.*(?:病历|健康|住址)|发布.*(?:隐私|照片)|支付|转账|签署|联系.*(?:Gabriel|加布里埃尔)|publish.*(?:medical|health|address|private)|transfer.*money|pay\b|sign\b|contact Gabriel/i.test(t);}
 function propose(s,id,intent,text,expected=s.serial){const n=scene(id);if(s.commits[id])return {already:true,record:s.commits[id]};if(id!==s.current_scene)throw Error('Inactive scene');if(expected!==s.serial)throw Error('Stale state');const b=n.branches.find(b=>b.intent===intent);if(!b)throw Error('Unknown intent');if(intent==='catchall')return {clarify:true,effects:{},advance:false};const proposal={scene_id:id,intent,text:String(text||''),expected_serial:s.serial,needs_confirmation:needsConfirmation(text),effects:copy(b.effects||{})};if(proposal.needs_confirmation)s.pending=proposal;return proposal;}
 function commit(s,p,confirmed=false){if(p.already)return p.record;if(p.clarify)return false;if(s.commits[p.scene_id])return s.commits[p.scene_id];if(s.serial!==p.expected_serial||s.current_scene!==p.scene_id)throw Error('Stale scene transaction');if(p.needs_confirmation&&!confirmed)return {pending:true};const next=copy(s),n=scene(p.scene_id),b=n.branches.find(b=>b.intent===p.intent);if(!b)throw Error('Unknown branch');for(const [k,v]of Object.entries(b.effects||{}))effect(next,k,v);for(const f of b.set_flags||[])next.flags[f]=true;for(const f of n.on_exit_flags||[])next.flags[f]=true;for(const [k,v]of Object.entries(n.evidence_linked_effects||{}))effect(next,k,v);const record=remember(next,n,{event_id:b.memory_key||b.branch_id,scene_id:n.node_id,recognized_action:b.intent,player_text:p.text,effects:copy(b.effects||{}),next_scene:n.next_node});next.commits[n.node_id]=record;next.pending=null;next.serial++;Object.assign(s,next);return record;}
 function cancel(s){s.pending=null;return true;}
 function game(s,id,result){const g=games.find(g=>g.id===id);if(!g)throw Error('Unknown game');if(g.scene_id!==s.current_scene)throw Error('Game outside its scene');if(s.games[id])return s.games[id];if(!['win','lose','skip'].includes(result))throw Error('Invalid game result');const next=copy(s),effects=result==='win'?g.win_effects:result==='lose'?g.lose_effects:g.skip_effects;for(const [k,v]of Object.entries(effects||{})){if(k==='set_flag')next.flags[v]=true;else if(k==='assisted_resolution')next.flags['assisted_'+id]=true;else effect(next,k,v);}next.flags['mg_'+id.toLowerCase()+'_done']=true;const record={event_id:'game:'+id,result,day:next.time.story_day,source:'verified_game',scene_id:g.scene_id,observers:scene(g.scene_id).characters.slice()};next.games[id]=record;next.memory.push(record);next.serial++;Object.assign(s,next);return record;}
 function caseStep(s,id,step,options={}){const spec=cases.find(c=>c[0]===id);if(!spec)throw Error('Unknown case');const ch=Number(scene(s.current_scene).chapter_id.slice(2));if(ch<spec[1])throw Error('Case not unlocked');const next=copy(s),c=next.cases[id]||(next.cases[id]={stage:0,consent_scope:[],deliverable:null,status:'offered'});if(c.status==='referred'||c.status==='delivered'||c.completed_steps?.includes(step))return c;c.completed_steps=c.completed_steps||[];if(step==='refer'){c.status='referred';c.deliverable={kind:'independent_referral',privacy:'private',owner:id};}else if(step==='authorize'){if(options.authorized!==true||!Array.isArray(options.scope)||!options.scope.length)throw Error('Express authorization required');c.consent_scope=options.scope.slice();c.stage=1;c.status='active';}else if(step===spec[3]||step===spec[4]){if(!c.consent_scope.length)throw Error('No case authorization');const expected=c.stage===1?spec[3]:c.stage===2?spec[4]:null;if(step!==expected)throw Error('Case step is out of order');c.stage++;}else if(step==='deliver'){if(c.stage!==3)throw Error('Case work incomplete');if(next.resource.legal_hours<spec[2])throw Error('Insufficient legal hours; use an independent referral');if(id==='CASE08'){const a=options.budget;if(!Array.isArray(a)||a.length!==4||a.some(n=>!Number.isFinite(n)||n<0)||a.reduce((a,b)=>a+b,0)>100||a[0]<45)throw Error('Budget must preserve operating costs and stay within 100');if(options.oliviaAuthority!==true)throw Error('Olivia must explicitly accept her decision-making role');next.flags.Olivia_partnership_approved=true;next.flags.budget_feasible=true;}next.resource.legal_hours-=spec[2];c.stage=4;c.status='delivered';c.deliverable={kind:spec[5],privacy:'case_private',owner:id,scope:c.consent_scope.slice(),finalCourtOrder:false};next.ledger.push({event_id:'case:'+id,legal_hours:-spec[2],cash_change:0,escrow_change:0,reason:'authorized_case_delivery'});}else throw Error('Unknown case step');c.completed_steps.push(step);next.serial++;next.memory.push({event_id:'case:'+id+':'+step,source:'case_action',privacy_classification:'case_private',observers:['player','Olivia'],consent_to_recall:false,action:step});Object.assign(s,next);return s.cases[id];}
 function relationship(s,who,decision,details={}){if(!['Gabriel','Theo'].includes(who)||!['decline','consider','date'].includes(decision))throw Error('Invalid relationship choice');if(decision==='decline'){s.relation[who].consent=false;s.relation[who].romance='declined';s.flags.player_declines_romance=true;s.route_choice='INDEPENDENT';return true;}if(decision==='consider'){s.relation[who].romance='considering';return true;}if(details.explicit!==true||details.npcConsent!==true)throw Error('Both people must expressly consent');if(who==='Gabriel'&&(s.character_arc.Gabriel_accountability<3||s.relation.Gabriel.trust<4||s.unresolved_conflict.some(x=>x.major&&!x.resolved)))throw Error('Accountability and repair are required');if(who==='Theo'&&(s.relation.Theo.trust<4||!s.flags.conflict_review_passed))throw Error('Independent conflict review is required');s.relation[who].consent=true;s.relation[who].romance='dating';s.route_choice=who==='Gabriel'?'GABRIEL_RECONCILE':'THEO_NEW_START';return true;}
 function ending(s){const m=s.metrics,p=s.plot;const event=s.flags.public_disclosure_authorized&&p.evidence_integrity>=8&&m.agency_ethics>=6?'EVIDENCE_PUBLIC':p.evidence_integrity>=5&&m.consent_respect>=4?'EVIDENCE_PRIVATE':m.clients_trust>=6?'TRUST_PROTECTED':'PARTIAL_ACCOUNTABILITY';let relationship='INDEPENDENT';if(s.route_choice==='GABRIEL_RECONCILE'&&s.relation.Gabriel.consent&&s.character_arc.Gabriel_accountability>=3&&s.relation.Gabriel.trust>=4&&!s.unresolved_conflict.some(x=>x.major&&!x.resolved))relationship='GABRIEL_RECONCILE';else if(s.route_choice==='THEO_NEW_START'&&s.relation.Theo.consent&&s.relation.Theo.trust>=4&&s.flags.conflict_review_passed)relationship='THEO_NEW_START';else if(s.flags.player_declines_romance)relationship='FRIENDSHIP';return {event,relationship,agency:s.flags.Olivia_partnership_approved&&s.flags.budget_feasible?'PARTNER_EXPAND':'BOUTIQUE_STUDIO',finalConviction:false,divorceFinalized:false};}
 function knowledge(s,who){return s.memory.filter(m=>m.observers?.includes(who)||m.privacy_classification==='public').map(copy);}
 function presentation(s,id){const n=scene(id),view={...n,characters:[...new Set([...n.characters,...n.dialogue.map(l=>l.speaker)])],dialogue:n.dialogue.map(copy),asset:n.bg,remote:[]};if(n.phone){view.characters=view.characters.filter(c=>c!=='Gabriel');view.remote=s.flags.m119_call_accepted?['Gabriel']:[];}if(id==='CH12_S04'){const who=s.relation.Gabriel.consent&&s.route_choice==='GABRIEL_RECONCILE'?'Gabriel':'Theo';view.characters=[who];view.dialogue=view.dialogue.filter(l=>l.speaker===who);view.asset=n.bg+'_'+who.toUpperCase();}if(id==='CH16_S03'){const route=ending(s).relationship,who=route==='GABRIEL_RECONCILE'?'Gabriel':route==='THEO_NEW_START'?'Theo':null;view.characters=who?[who]:[];view.dialogue=view.dialogue.filter(l=>who?l.speaker===who:l.speaker==='Olivia').map(l=>who?l:{...l,delivery:'previously_received_message'});view.asset=n.bg+'_'+(who?who.toUpperCase():'SOLO');}if(id==='CH16_S04'){const returns=s.cases.CASE01?.status==='delivered';view.characters=returns?['Olivia','Vivian']:['Olivia'];view.dialogue=view.dialogue.filter(l=>returns||l.speaker!=='Vivian');view.asset=n.bg+(returns?'_VIVIAN':'');}return view;}
